const wb=$('Webhook').first().json.body||{};
const name=wb.customer_name||'Unknown';
const disc=parseInt(wb.proposed_discount_pct)||10;
const rows=$('Get Customer Data').all().filter(r=>r.json&&r.json.customer_id);
if(!rows.length){
  return [{json:{error:true,message:'Customer not found: '+name,
    clv:0,recommendation:'reject',financial_rationale:'Customer not found in database.',llm_source:'system'}}];
}
const r=rows[0].json;
const oc=parseInt(r.order_count)||0;
const ts=parseFloat(r.total_spent)||0;
const ao=oc>0?ts/oc:0;
const yr=Math.max((Date.now()-new Date(r.created_at).getTime())/(365.25*24*3600*1000),0.1);
const clv=Math.round(ao*oc);
const prompt='Pharmacy finance decision for '+r.full_name+': CLV='+clv+' EGP, avg_order='+Math.round(ao)+' EGP, total_orders='+oc+', proposed_discount='+disc+'%. Answer ONLY: DECISION: [approve/reduce/reject] | REASON: [one sentence]';
return [{json:{customer_id:r.customer_id,full_name:r.full_name,clv,avg_order:Math.round(ao),order_count:oc,years_as_customer:parseFloat(yr.toFixed(1)),discount_pct:disc,ollama_prompt:prompt,error:false}}];

const calc=$('Calculate CLV').first().json;
if(calc.error)return [{json:calc}];
const raw=$('Ask Ollama').first().json.response||'';
const dm=raw.match(/DECISION:\s*(approve|reduce|reject)/i);
const rm=raw.match(/REASON:\s*(.+?)(?:\n|$)/i);
return [{json:{
  customer_name:calc.full_name,
  clv:calc.clv,
  avg_order_value:calc.avg_order,
  order_count:calc.order_count,
  years_as_customer:calc.years_as_customer,
  proposed_discount_pct:calc.discount_pct,
  recommendation:dm?dm[1].toLowerCase():'reduce',
  financial_rationale:rm?rm[1].trim():raw.slice(0,250).trim(),
  llm_source:'ollama:AI-COS-LFM-Q4'
}}];
